WITH enriched AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, AVG(discount_pct) OVER (PARTITION BY channel ORDER BY starts_on, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS discount_pct_avg_6, SUM(discount_pct) OVER (PARTITION BY channel, promo_code ORDER BY ends_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_discount_pct, LEAD(discount_pct, 1) OVER (PARTITION BY promo_code, channel ORDER BY discount_pct, id) AS next_discount_pct FROM promotions) SELECT DATE_TRUNC('YEAR', ends_on) AS year_start, CASE WHEN next_discount_pct >= 0.33 THEN 'HIGH' ELSE 'LOW' END AS next_discount_pct_tier, CASE WHEN discount_pct >= 0.32 THEN 'HIGH' ELSE 'LOW' END AS discount_pct_tier, SUM(CASE WHEN promo_code = 'WELCOME5' THEN discount_pct_avg_6 ELSE 0 END) AS welcome5_discount_pct_avg_6, COUNT(*) FILTER (WHERE channel = 'partner') AS partner_rows, ROUND(SUM(next_discount_pct) / NULLIF(COUNT(CASE WHEN promo_code = 'VIP' THEN 1 END), 0), 2) AS next_discount_pct_per_vip, SORT_ARRAY(COLLECT_SET(promo_code)) AS promo_code_list, COUNT(*) AS event_count, SUM(CASE WHEN promo_code = 'VIP' THEN discount_pct_avg_6 ELSE 0 END) AS vip_discount_pct_avg_6 FROM enriched GROUP BY GROUPING SETS ((DATE_TRUNC('YEAR', ends_on), CASE WHEN next_discount_pct >= 0.33 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN discount_pct >= 0.32 THEN 'HIGH' ELSE 'LOW' END), (DATE_TRUNC('YEAR', ends_on), CASE WHEN next_discount_pct >= 0.33 THEN 'HIGH' ELSE 'LOW' END), (DATE_TRUNC('YEAR', ends_on)), ()) HAVING SUM(CASE WHEN promo_code = 'WELCOME5' THEN discount_pct_avg_6 ELSE 0 END) < 0
